from typing import List

class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        result = []
        path = []

        def dfs() -> None:
            if len(path) == len(nums):
                if len(set(path)) == len(nums):
                    result.append(path.copy())
                return
            for value in nums:
                path.append(value)
                dfs()
                path.pop()

        dfs()
        return result

